using namespace std;
int main() {
	int n; cin >> n;
	vector<int> a(n);
	for (int i=0; i<n; i++) {
		cin >> a[i];
	}
	vector<int> val = {int(1e9)}; // stack の値
	vector<int> ind = {-1}; // その座標
	for (int i=0; i<n; i++) {
		while (val.back() <= a[i]) {
			val.pop_back();
			ind.pop_back();
		}
		cout << ind.back() << '\n';
		val.push_back(a[i]);
		ind.push_back(i + 1);
	}
}
